const builderJson = useMemo<{ stack: string; port: number } | null>(() => {
if (!project?.builder_json) return null;
try {
const cfg = JSON.parse(project.builder_json) as { stack?: string; port?: number };
return cfg.stack && cfg.port ? { stack: cfg.stack, port: cfg.port } : null;
} catch {
return null;
}
}, [project?.builder_json]);

const pump = useCallback(() => {
if (!el || speed.current === 0) {
frame.current = null;
return;
}
el.scrollTop += speed.current;
frame.current = requestAnimationFrame(pump);
}, [el]);

const selectActiveFile = useMemo(() => {
let previous: ReturnType<typeof useWorkspaceStore.getState>['openFiles'][number] | null = null;
return (state: ReturnType<typeof useWorkspaceStore.getState>) => {
const next = state.openFiles.find(
(file) => file.path === activePath && file.projectId === state.activeProjectId,
) ?? null;
if (activeFileRenderEqual(previous, next)) return previous;
previous = next;
return next;
};
}, [activePath]);

const selectTabFiles = useMemo(() => {
let previous: OpenTab[] = [];
return (state: ReturnType<typeof useWorkspaceStore.getState>) => {
const next = state.openFiles;
if (previous.length === next.length && previous.every((file, index) => tabBarFileEqual(file, next[index]))) {
return previous;
}
previous = next;
return next;
};
}, []);

reloadCoordinator.setRunner(async ({ silent, isCurrent }) => {
const includeFiles = tab === 'changes';
if (!silent) setLoading(true);
const finishStatusSpan = startRouteSpan('GitWindow:status', {
projectId,
tab: 'git',
detail: includeFiles ? 'full' : 'summary',
});
const finishMergeSpan = startRouteSpan('GitWindow:mergeState', { projectId, tab: 'git' });
try {
const [s, ms] = await Promise.all([
(includeFiles
? loadCompleteStatus(projectId, repoPath)
: apiCall<GitStatus>('projectGit.status', { projectId, repoPath, includeFiles: false })
.then((value) => ({ ...value, counts: null })))
.then((value) => {
finishStatusSpan({ status: 'ok' });
return value;
})
.catch((err) => {
finishStatusSpan({ status: 'error', error: err instanceof Error ? err.message : String(err) });
throw err;
}),
apiCall<GitMergeState>('projectGit.mergeState', { projectId, repoPath })
.then((value) => {
finishMergeSpan({ status: 'ok' });
return value;
})
.catch((err) => {
finishMergeSpan({ status: 'error', error: err instanceof Error ? err.message : String(err) });
throw err;
}),
]);
if (!isCurrent()) return;
setStatus(s);
setStatusCounts(s.counts);
setMergeState(ms);
staleWhileHidden.current = false;
// Feed the editor's conflict registry (project-relative paths) so open
// files light up inline. mergeState paths are repoRoot-relative, so for a
// submodule we prefix them with the active repo's project-relative prefix.
const prefix = repoPrefix ?? '';
if (ms.kind) {
const rebased = prefix ? ms.conflictedFiles.map((f) => `${prefix}/${f}`) : ms.conflictedFiles;
setConflicts(projectId, prefix, rebased);
} else {
clearConflicts(projectId, prefix);
}
setError(null);
} catch (err) {
if (isCurrent()) setError(err instanceof Error ? err.message : String(err));
} finally {
if (isCurrent()) setLoading(false);
}
});
